let products=[],cart=[];try{cart=JSON.parse(localStorage.getItem('egattoc-bag')||'[]');if(!Array.isArray(cart))cart=[]}catch{}const main=document.querySelector('main'),money=n=>n.toLocaleString('ko-KR')+'원',esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const cats={EAT:['Food & Tea',''],MOVE:['Movement',''],MIND:['Body Care',''],SLEEP:['Rest','']};
function card(p){return `<article class="product"><div class="product-image"><a href="#/product/${p.id}"><img src="${p.image}" alt="${esc(p.brand+' '+p.name)}" loading="lazy"></a><span class="tag">${p.category}</span><button class="add" data-add="${p.id}" aria-label="${esc(p.name)} 장바구니 담기">+</button></div><div class="product-info"><a href="#/brands/${encodeURIComponent(p.brand)}" class="brand">${esc(p.brand)}</a><a href="#/product/${p.id}"><h3>${esc(p.name)}</h3></a><p class="price">${money(p.price)}</p></div></article>`}
const grid=ps=>`<div class="products">${ps.map(card).join('')}</div>`;
function home(){return `<section class="hero"><div class="hero-copy"><span class="eyebrow">EGATTOC WELLNESS MARKET</span><h1>Good things.<br>Every day.</h1><p>Food, tea & body care.</p><a class="button" href="#/shop">Explore the shop <span>↗</span></a></div><a class="hero-visual" href="#/product/26"><img class="hero-photo" src="assets/product-26.webp" alt="EGATTOC 오일 스크럽" fetchpriority="high" loading="eager"><span>EGATTOC · Oil Scrub ↗</span></a></section><section class="section"><div class="section-head"><div><span class="eyebrow">THE EDIT</span><h2>Selected essentials</h2></div><a class="text-link" href="#/shop">Shop all ↗</a></div>${grid([products[3],products[2],products[4],products[6]])}</section><section class="section"><div class="section-head"><h2>Find your everyday</h2></div><div class="rituals"><a class="ritual-card" href="#/shop/EAT"><img src="assets/product-27.webp" alt="본디 오르조" loading="lazy"><div><span class="eyebrow">EAT</span><h3>Food & Tea</h3><span>Explore ↗</span></div></a><a class="ritual-card" href="#/shop/MIND"><img src="assets/product-25.webp" alt="EGATTOC 소프트 스크럽" loading="lazy"><div><span class="eyebrow">MIND</span><h3>Body Care</h3><span>Explore ↗</span></div></a></div></section><section class="editorial"><img class="editorial-photo" src="assets/event.webp" alt="차 한 잔을 들고 있는 모습" loading="lazy"><div class="editorial-copy"><span class="eyebrow">ABOUT THE MARKET</span><h2>A little more<br>considered.</h2><p>Tea, food and body care.<br>Discover EGATTOC and the brands in our market.</p><a class="text-link" href="#/story">About EGATTOC ↗</a></div></section><section class="section brands-section"><div class="section-head"><h2>Our brands</h2><a class="text-link" href="#/brands">View all ↗</a></div><div class="brand-marquee"><div class="brand-track">${[false,true].map(copy=>`<div class="brand-group" ${copy?'aria-hidden="true"':''}>${[...new Set(products.map(p=>p.brand))].map(b=>`<a href="#/brands/${encodeURIComponent(b)}" ${copy?'tabindex="-1"':''}>${esc(b)}</a><span>✳</span>`).join('')}</div>`).join('')}</div></div></section>${discoveryStrip()}`}

function journalCards(){return `<div class="journal-grid"><a href="#/story"><img src="assets/walk.webp" alt="숲길을 걷는 모습" loading="lazy"><span class="brand">About</span><h3>About EGATTOC</h3><p>The market. The brands.</p></a><a href="#/shop/EAT"><img src="assets/product-22.webp" alt="에가톳 솔트 티" loading="lazy"><span class="brand">Products</span><h3>White Mineral Salt Tea</h3><p>Tea & Drinks.</p></a><a href="https://egattoc.life/board/product/list.html?board_no=4" target="_blank" rel="noopener"><img src="assets/event.webp" alt="차를 마시는 모습" loading="lazy"><span class="brand">Reviews</span><h3>Reviews</h3><p>Read reviews on our store.</p></a></div>`}
function pageHead(title,sub){return `<section class="page-head"><div class="breadcrumb"><a href="#/">HOME</a> / ${esc(title.toUpperCase())}</div><h1>${esc(title)}</h1><p>${esc(sub)}</p></section>`}
function listing(kind,value){let ps=products;let title='Shop all',sub='';if(kind==='shop'&&cats[value]){ps=ps.filter(p=>p.category===value);title=cats[value][0];sub=''}if(kind==='shop'&&['MOVE','SLEEP'].includes(value)&&!ps.length)return categoryGuide(value);if(kind==='brands'&&value){ps=ps.filter(p=>(p.brand===value||p.brandKo===value));title=value;sub=''}if(kind==='search'){let q=value.toLowerCase();ps=ps.filter(p=>(p.name+p.brand+(p.brandKo||'')+p.category).toLowerCase().includes(q));title='Search';sub='“'+value+'” 검색 결과'}return pageHead(title,sub)+`<section class="section"><div class="filterbar"><div class="filter-tabs">${['ALL','EAT','MIND'].map(c=>`<a class="${(value===c||(!value&&c==='ALL'))?'active':''}" href="#/shop${c==='ALL'?'':'/'+c}">${c==='ALL'?'All':cats[c][0]}</a>`).join('')}</div><label>Sort <select id="sort"><option value="default">Featured</option><option value="low">Price: Low to high</option><option value="high">Price: High to low</option><option value="name">Name</option></select></label></div><p class="results-count">${ps.length} products</p><div id="listingGrid" data-ids="${ps.map(p=>p.id).join(',')}">${ps.length?grid(ps):`<div class="empty"><h2>${kind==='search'?'검색 결과가 없습니다.':'등록된 상품이 없습니다.'}</h2><p class="muted">${kind==='search'?'다른 상품명이나 브랜드명으로 검색해 보세요.':'이 카테고리의 상품은 아직 등록되지 않았습니다. Shop all에서 다른 제품을 확인해 주세요.'}</p><a class="button" href="#/shop">Shop all</a></div>`}</div></section>`}
function detail(id){let p=products.find(p=>p.id===Number(id));if(!p)return pageHead('상품을 찾을 수 없습니다','Shop all에서 제품을 선택해 주세요.')+listing('shop','');return `<div class="detail"><div><div class="breadcrumb"><a href="#/">HOME</a> / <a href="#/shop/${p.category}">${p.category}</a> / ${esc(p.brand)}</div><div class="detail-photo"><img loading="eager" src="${p.image}" alt="${esc(p.name)}"></div></div><div class="detail-copy"><a class="brand" href="#/brands/${encodeURIComponent(p.brand)}">${esc(p.brand)} ↗</a><h1>${esc(p.name)}</h1><p class="price">${money(p.price)}</p><p class="detail-note">${esc(p.brand)} · ${cats[p.category][0]}</p><div class="purchase"><div class="quantity"><button id="qtyMinus" disabled aria-label="수량 줄이기">−</button><output id="productQty">1</output><button id="qtyPlus" aria-label="수량 늘리기">+</button></div><button class="button" data-add="${p.id}" data-detail="true">장바구니 담기 +</button></div><a class="external button outline" href="${p.url}" target="_blank" rel="noopener">공식몰에서 옵션 선택·구매 ↗</a><details open><summary>상품 안내</summary><p>상품명: ${esc(p.brand+' '+p.name)}<br>선택한 구성과 옵션에 따라 가격이 달라질 수 있습니다.</p></details><details><summary>성분 및 상세 정보</summary><p>전성분, 원산지, 섭취·사용법은 공식 상품 페이지에서 확인할 수 있습니다. <a href="${p.url}" target="_blank" rel="noopener">상품 상세 확인 ↗</a></p></details><details><summary>배송 및 교환</summary><p>상품별 배송비와 교환·반품 조건은 공식몰의 구매 안내를 확인해 주세요.</p></details></div></div><section class="section"><div class="section-head"><h2>You may also like</h2><a class="text-link" href="#/shop">Shop all</a></div>${grid(products.filter(q=>q.id!==p.id).sort((a,b)=>Number(b.category===p.category)-Number(a.category===p.category)).slice(0,4))}</section>`}
function story(){return pageHead('About EGATTOC','Wellness Market')+`<section class="editorial"><img class="editorial-photo" src="assets/event.webp" alt="차를 들고 있는 모습" loading="lazy"><div class="editorial-copy"><span class="eyebrow">THE MARKET</span><h2>Food. Tea.<br>Body care.</h2><p>From mineral salt tea to body scrubs, explore products from EGATTOC, looup, BONDI, AVO and PUNGGIAESAM.</p><a class="text-link" href="#/shop">Explore the shop ↗</a></div></section><section class="section"><div class="section-head"><h2>Explore the collections</h2></div><div class="category-links"><a href="#/shop/EAT"><span>EAT</span><h3>Food & Tea ↗</h3></a><a href="#/shop/MIND"><span>MIND</span><h3>Body Care ↗</h3></a></div></section>`}

function render(){const parts=location.hash.replace(/^#\/?/,'').split('/').map(s=>{try{return decodeURIComponent(s)}catch{return s}});let [page,value]=parts;document.body.classList.toggle('is-home',!page);document.querySelector('#mobileMenu').close();document.querySelector('#menuToggle').setAttribute('aria-expanded','false');main.innerHTML=optimiseMarkup(!page?home():page==='shop'||page==='search'||page==='brands'&&value?listing(page,value||''):page==='product'?detail(value):page==='story'?story():page==='journal'?pageHead('Journal','')+`<section class="section">${journalCards()}</section>`:page==='brands'?pageHead('Brands','Our Brands')+`<section class="section brand-cards">${[...new Set(products.map(p=>p.brand))].map(b=>`<a href="#/brands/${encodeURIComponent(b)}"><h2>${b}</h2><p>Shop collection ↗</p></a>`).join('')}</section>`:page==='account'?pageHead('마이페이지','주문과 배송 정보를 확인하세요.')+`<section class="account-panel"><h2>EGATTOC 회원 서비스</h2><p class="muted">주문 내역, 배송 조회와 작성한 리뷰는 기존 EGATTOC 공식몰 계정에서 확인할 수 있습니다.</p><a class="button" href="https://egattoc.life/member/login.html" target="_blank" rel="noopener">공식몰 로그인 ↗</a></section>`:pageHead('페이지를 찾을 수 없습니다','메뉴에서 원하는 페이지를 선택해 주세요.'));document.title=page?`${page==='product'?products.find(p=>p.id==value)?.name||'Product':value||page.toUpperCase()} — EGATTOC`:'EGATTOC — Wellness Life Market';window.scrollTo({top:0,behavior:"instant"});setupReveal();let sort=document.querySelector('#sort');if(sort)sort.onchange=()=>{let target=document.querySelector('#listingGrid'),ids=target.dataset.ids.split(',').map(Number),ps=products.filter(p=>ids.includes(p.id));if(sort.value==='low')ps.sort((a,b)=>a.price-b.price);if(sort.value==='high')ps.sort((a,b)=>b.price-a.price);if(sort.value==='name')ps.sort((a,b)=>a.name.localeCompare(b.name,'ko'));if(ps.length)target.innerHTML=optimiseMarkup(grid(ps))};document.querySelector('#qtyMinus')?.addEventListener('click',()=>quantity(-1));document.querySelector('#qtyPlus')?.addEventListener('click',()=>quantity(1))}
function quantity(delta){let out=document.querySelector('#productQty');out.value=String(Math.max(1,Math.min(99,Number(out.value)+delta)));document.querySelector('#qtyMinus').disabled=Number(out.value)===1;document.querySelector('#qtyPlus').disabled=Number(out.value)===99}
function persist(){try{localStorage.setItem('egattoc-bag',JSON.stringify(cart))}catch{}document.querySelector('#cartCount').textContent=cart.reduce((s,c)=>s+c.qty,0)}
let toastTimer;function toast(t){let el=document.querySelector('#toast');el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2400)}
function showCart(){document.querySelector('#bagCount').textContent='('+cart.reduce((s,c)=>s+c.qty,0)+')';document.querySelector('#cartItems').innerHTML=cart.length?cart.map(c=>{let p=products.find(p=>p.id===c.id);return `<div class="cart-row"><a href="#/product/${p.id}" data-close><img src="${p.image.replace('.webp','-480.webp')}" alt="${esc(p.name)}"></a><div class="cart-info"><span class="brand">${p.brand}</span><h3>${p.name}</h3><p class="price">${money(p.price*c.qty)}</p><div class="quantity"><button data-quantity="${c.id}" data-delta="-1" ${c.qty<=1?'disabled':''} aria-label="${esc(p.name)} 수량 줄이기">−</button><output>${c.qty}</output><button data-quantity="${c.id}" data-delta="1" ${c.qty>=99?'disabled':''} aria-label="${esc(p.name)} 수량 늘리기">+</button></div><button class="remove" data-remove="${c.id}">삭제</button><a href="${p.url}" target="_blank" rel="noopener" class="cart-buy">공식몰 구매 ↗</a></div></div>`}).join(''):'<div class="empty"><div class="empty-bag-icon"><svg viewBox="0 0 64 72" aria-hidden="true"><path d="M10 22h44l4 44H6l4-44ZM22 25V16a10 10 0 0 1 20 0v9"/></svg></div><span class="eyebrow">YOUR PERSONAL EDIT</span><h3>Your bag awaits.</h3><p class="muted">마음에 드는 제품을 담아보세요.</p><button class="button" data-close>쇼핑 계속하기</button></div>';document.querySelector('#cartTotal').innerHTML=cart.length?`<div class="sum"><span>상품 합계</span><strong>${money(cart.reduce((s,c)=>s+products.find(p=>p.id===c.id).price*c.qty,0))}</strong></div><p class="cart-disclaimer">구매는 공식몰에서 진행됩니다.<br>상품별 구매 링크에서 옵션과 수량을 선택해 주세요.</p><button class="continue-shopping" data-close>계속 쇼핑하기</button>`:''}
document.addEventListener('click',e=>{const add=e.target.closest('[data-add]');if(add){let id=Number(add.dataset.add),qty=add.dataset.detail?Number(document.querySelector('#productQty').value):1,existing=cart.find(c=>c.id===id);if(existing)existing.qty=Math.min(99,existing.qty+qty);else cart.push({id,qty});persist();toast('장바구니에 담았습니다.');return}const del=e.target.closest('[data-remove]'),q=e.target.closest('[data-quantity]');if(del){cart=cart.filter(c=>c.id!==Number(del.dataset.remove));persist();showCart()}if(q){let c=cart.find(c=>c.id===Number(q.dataset.quantity));c.qty=Math.max(1,Math.min(99,c.qty+Number(q.dataset.delta)));persist();showCart()}if(e.target.closest('[data-close]'))e.target.closest('dialog')?.close();const link=e.target.closest('a[href^="#"]');if(link){document.querySelectorAll('dialog[open]').forEach(d=>d.close())}});
document.querySelector('#cartToggle').onclick=()=>{showCart();document.querySelector('#cartDialog').showModal()};document.querySelector('#searchToggle').onclick=()=>{document.querySelector('#searchDialog').showModal();updateSearch();document.querySelector('#searchInput').focus()};document.querySelector('#searchForm').onsubmit=e=>{e.preventDefault();const q=document.querySelector('#searchInput').value.trim();if(q){document.querySelector('#searchDialog').close();location.hash='/search/'+encodeURIComponent(q)}};document.querySelector('#menuToggle').onclick=()=>{document.querySelector('#mobileMenu').showModal();document.querySelector('#menuToggle').setAttribute('aria-expanded','true')};document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));window.addEventListener('hashchange',render);fetch('catalog.json').then(r=>{if(!r.ok)throw Error('catalog');return r.json()}).then(data=>{products=data;cart=cart.filter(c=>c&&typeof c==='object'&&products.some(p=>p.id===c.id)&&Number.isInteger(c.qty)&&c.qty>0&&c.qty<=99);persist();render()}).catch(()=>{main.innerHTML=pageHead('잠시 후 다시 방문해 주세요.','상품 정보를 불러오지 못했습니다. 새로고침해 주세요.')});

function categoryGuide(category){const sleep=category==='SLEEP';return pageHead(category,cats[category].filter(Boolean).join(' — '))+`<section class="category-guide"><img src="assets/${sleep?'sleep.webp':'walk.webp'}" alt="${sleep?'휴식을 위한 시간':'숲길을 걷는 모습'}"><div><span class="guide-label">${cats[category][0]}</span><h2>${sleep?'Rest & Recharge':'Everyday Movement'}</h2><p>${sleep?'A collection for rest. Coming soon.':'A collection for movement. Coming soon.'}</p><p class="inventory-note">Coming soon.</p><a class="button outline" href="#/shop">Shop all <span>→</span></a></div></section><section class="section"><div class="section-head"><h2>Explore more</h2></div><div class="category-links"><a href="#/shop/EAT"><span>EAT</span><h3>Food & Tea</h3><span>→</span></a><a href="#/shop/MIND"><span>MIND</span><h3>Body Care</h3><span>→</span></a></div></section>`}

function updateSearch(){const input=document.querySelector('#searchInput'),q=input.value.trim().toLowerCase();document.querySelector('#searchClear').hidden=!q;document.querySelector('#searchSuggestions').hidden=!!q;const results=document.querySelector('#searchResults');if(!q){results.innerHTML='';return}const found=products.filter(p=>(p.name+p.brand+(p.brandKo||'')+p.category).toLowerCase().includes(q));results.innerHTML=found.length?`<p class="search-label">${found.length}개 상품</p><div class="search-list">${found.slice(0,5).map(p=>`<a class="search-result" href="#/product/${p.id}"><img src="${p.image.replace('.webp','-480.webp')}" alt=""><span><small>${esc(p.brand)}</small><strong>${esc(p.name)}</strong></span><b>${money(p.price)}</b></a>`).join('')}</div><button class="all-results" type="submit">검색 결과 전체 →</button>`:'<p class="search-empty">검색 결과가 없습니다.<br><span>상품명이나 브랜드명을 다시 확인해 주세요.</span></p>'}
document.querySelector('#searchInput').addEventListener('input',updateSearch);document.querySelector('#searchClear').onclick=()=>{document.querySelector('#searchInput').value='';updateSearch();document.querySelector('#searchInput').focus()};document.querySelectorAll('[data-query]').forEach(b=>b.onclick=()=>{document.querySelector('#searchInput').value=b.dataset.query;updateSearch()});document.querySelectorAll('dialog').forEach(d=>d.addEventListener('close',()=>{if(d.id==='mobileMenu')document.querySelector('#menuToggle').setAttribute('aria-expanded','false')}));

function optimiseMarkup(html){return html.replace(/<img\b[^>]*>/g,tag=>{const match=tag.match(/src="(assets\/[^" ]+\.webp)"/);if(!match)return tag;const large=match[1],small=large.replace('.webp','-480.webp'),hero=tag.includes('hero-photo'),detail=html.includes('detail-photo')&&tag.includes('loading="eager"');return tag.replace(`src="${large}"`,`src="${small}" srcset="${small} 480w, ${large} ${photoWidths[large]||1200}w" sizes="${hero?'(max-width:700px) 100vw, 55vw':detail||tag.includes('editorial-photo')||tag.includes('style=')||html.includes('category-guide')?'(max-width:700px) 100vw, 50vw':'(max-width:700px) 50vw, 25vw'}" decoding="async"`).replace(/>$/,`${tag.includes('loading=')?'':' loading="lazy"'}>`)});}

const photoWidths={"assets/product-40.webp": 680, "assets/product-41.webp": 680, "assets/product-27.webp": 678, "assets/product-26.webp": 1600, "assets/event.webp": 1200, "assets/product-25.webp": 680, "assets/sleep.webp": 1200, "assets/walk.webp": 1200, "assets/product-39.webp": 679, "assets/product-42.webp": 680, "assets/product-22.webp": 800, "assets/product-34.webp": 677};

function discoveryStrip(){const items=products.slice(0,6);const group=hidden=>`<div class="discovery-group" ${hidden?'aria-hidden="true"':''}>${items.map(p=>`<a class="discovery-card" href="#/product/${p.id}" ${hidden?'tabindex="-1"':''}><img src="${p.image}" alt="" loading="lazy"><div><span>${esc(p.brand)}</span><h3>${esc(p.name)}</h3><p>${money(p.price)}</p></div><b aria-hidden="true">↗</b></a>`).join('')}</div>`;return `<section class="discovery"><div class="discovery-heading"><span>THE EGATTOC COLLECTION</span><h2>Explore the collection</h2><a href="#/shop">Shop all ↗</a></div><div class="discovery-window"><div class="discovery-track">${group(false)}${group(true)}</div></div></section>`}

function updateNavigation(){const current=location.hash||'#/';document.querySelectorAll('header nav a,.drawer-nav a').forEach(a=>{const selected=a.getAttribute('href')===current;a.toggleAttribute('data-active',selected);if(selected)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')})}window.addEventListener('hashchange',updateNavigation);updateNavigation();

let revealObserver;function setupReveal(){revealObserver?.disconnect();if(!matchMedia('(max-width:700px)').matches||matchMedia('(prefers-reduced-motion:reduce)').matches)return;revealObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');revealObserver.unobserve(entry.target)}}),{threshold:.06,rootMargin:'0px 0px 28px 0px'});document.querySelectorAll('main .section-head,main .journal-grid>a,main .editorial,main .ritual-card,main .pillar-intro').forEach(el=>{if(el.getBoundingClientRect().top>innerHeight){el.classList.add('scroll-reveal');revealObserver.observe(el)}})}
